import { expect, test, uniqueName } from "../../fixtures";

test("submitting with missing documents lists what is missing", { tag: "@REV-02" }, async ({ apiAs }) => {
  // Arrange: a draft vendor with only an extracted w9 document
  const member = await apiAs("member");

  const created = await member.post("/api/vendors", {
    data: {
      name: uniqueName("REV02 Vendor"),
      category: "software",
      contact_email: `rev02.${Date.now().toString(36)}${Math.random().toString(36).slice(2, 6)}@example.com`,
    },
  });
  expect(created.status(), await created.text()).toBe(201);
  const vendor = await created.json();

  const upload = await member.post(`/api/vendors/${vendor.id}/documents`, {
    multipart: {
      kind: "w9",
      file: {
        name: "w9.pdf",
        mimeType: "application/pdf",
        buffer: Buffer.from("%PDF-1.4\n% w9 test document\n%%EOF\n"),
      },
    },
  });
  expect(upload.status(), await upload.text()).toBe(201);
  const document = await upload.json();

  // Extraction runs in the background; wait until it finishes.
  await expect
    .poll(async () => {
      const res = await member.get(`/api/documents/${document.id}`);
      expect(res.status(), await res.text()).toBe(200);
      return (await res.json()).status;
    })
    .toBe("extracted");

  // Act
  const response = await member.post(`/api/vendors/${vendor.id}/submit`);

  // Assert
  const body = await response.text();
  expect(response.status(), body).toBe(409);
  const parsed = JSON.parse(body);
  expect(parsed.error?.code ?? parsed.detail?.error?.code, body).toBe("documents_incomplete");
  const serialized = JSON.stringify(parsed);
  expect(serialized, body).toContain("contract");
  expect(serialized, body).toContain("insurance_certificate");
});
